CREATE TABLE transcript_sources(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES agent_sessions(id),runtime_id TEXT REFERENCES session_runtimes(id),kind TEXT NOT NULL CHECK(kind IN ('acp_stream','native_import')),source_key TEXT NOT NULL,format_version TEXT NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,coverage TEXT NOT NULL CHECK(coverage IN ('complete','partial','unknown')),created_at TEXT NOT NULL,UNIQUE(session_id,kind,source_key));
